        /// Removes <see cref="InputAction.started"/>, <see cref="InputAction.performed"/> and <see cref="InputAction.canceled"/> callbacks provided via <param cref="instance" /> on all input actions contained in this map.
        /// </summary>
        /// <remarks>
        /// Calling this method when <paramref name="instance" /> have not previously been registered has no side-effects.
        /// </remarks>
        /// <seealso cref="GameSelectionActions" />
        private void UnregisterCallbacks(IGameSelectionActions instance)
        {
            @NavList.started -= instance.OnNavList;
            @NavList.performed -= instance.OnNavList;
            @NavList.canceled -= instance.OnNavList;
            @Select.started -= instance.OnSelect;
            @Select.performed -= instance.OnSelect;
            @Select.canceled -= instance.OnSelect;
        }

        /// <summary>
        /// Unregisters <param cref="instance" /> and unregisters all input action callbacks via <see cref="GameSelectionActions.UnregisterCallbacks(IGameSelectionActions)" />.
        /// </summary>
        /// <seealso cref="GameSelectionActions.UnregisterCallbacks(IGameSelectionActions)" />
        public void RemoveCallbacks(IGameSelectionActions instance)
        {
            if (m_Wrapper.m_GameSelectionActionsCallbackInterfaces.Remove(instance))
                UnregisterCallbacks(instance);
        }

        /// <summary>
        /// Replaces all existing callback instances and previously registered input action callbacks associated with them with callbacks provided via <param cref="instance" />.
        /// </summary>
        /// <remarks>
        /// If <paramref name="instance" /> is <c>null</c>, calling this method will only unregister all existing callbacks but not register any new callbacks.
        /// </remarks>
        /// <seealso cref="GameSelectionActions.AddCallbacks(IGameSelectionActions)" />
        /// <seealso cref="GameSelectionActions.RemoveCallbacks(IGameSelectionActions)" />
        /// <seealso cref="GameSelectionActions.UnregisterCallbacks(IGameSelectionActions)" />
        public void SetCallbacks(IGameSelectionActions instance)
        {
            foreach (var item in m_Wrapper.m_GameSelectionActionsCallbackInterfaces)
                UnregisterCallbacks(item);
            m_Wrapper.m_GameSelectionActionsCallbackInterfaces.Clear();
            AddCallbacks(instance);
        }
    }
